import { SearchOutlined } from '@ant-design/icons';
import React, { useRef, useState, useEffect } from 'react';
import Highlighter from 'react-highlight-words';
import { Button, Input, Space, Table, Tag } from 'antd';
import { Link, useNavigate} from "react-router-dom";
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';
import DeleteOutlinedIcon from '@mui/icons-material/DeleteOutlined';
import { useSelector } from 'react-redux';
import { Chip, Stack } from '@mui/material';
import SentimentDissatisfiedOutlinedIcon from '@mui/icons-material/SentimentDissatisfiedOutlined';
import SentimentSatisfiedOutlinedIcon from '@mui/icons-material/SentimentSatisfiedOutlined';
import './data-embarcador.css'
import firebase from '../../config/firebase';
import InputMask from 'react-input-mask';
require('firebase/auth')

const DataDriverTable = ({data}) => {

  // console.log(data);
  data.sort((a, b) => {
    return b.accountCreated.seconds - a.accountCreated.seconds || b.accountCreated.nanoseconds - a.accountCreated.nanoseconds;
  });

  let navigate = useNavigate();
  const user = useSelector(state => state.user)

  const [searchText, setSearchText] = useState('');
  const [searchedColumn, setSearchedColumn] = useState('');
  const searchInput = useRef(null);
  const [datas, setData] = useState([]);

  const fetchData = async () => {
    const snapshot = await firebase.firestore().collection('drivers_users').get();
    const documents = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    documents.sort((a, b) => {
      return b.accountCreated.seconds - a.accountCreated.seconds || b.accountCreated.nanoseconds - a.accountCreated.nanoseconds;
    });
    setData(documents);
  };

  useEffect(() => {
    fetchData();
  }, []);
  
  // const handleSearch = (selectedKeys, confirm, dataIndex) => {
  //   console.log(selectedKeys);
  //   if (selectedKeys[0].length > 0) {
  //     selectedKeys = selectedKeys[0].replace(/[.-]/g, '');
  //     confirm();
  //     setSearchText(selectedKeys[0]);
  //     setSearchedColumn(dataIndex);
  //   } else {
  //     confirm();
  //     setSearchText(selectedKeys[0]);
  //     setSearchedColumn(dataIndex);
  //   }
  // };
  const handleSearch = (selectedKeys, confirm, dataIndex) => {
    if (selectedKeys.length > 0) {
      selectedKeys[0] = selectedKeys[0].replace(/[.-]/g, '');
      if (selectedKeys[0].trim().length > 0) {
        confirm();
        setSearchText(selectedKeys[0]);
        setSearchedColumn(dataIndex);
      } else {
        confirm();
        setSearchText('');
        setSearchedColumn(dataIndex);
      }
    } else {
      confirm();
      setSearchText('');
      setSearchedColumn(dataIndex);
    }
  };
  
  const handleReset = (clearFilters) => {
    clearFilters();
    setSearchText('');
  };

  // function renderStatusColor(status){
  //   if(status === "incomplete") {
  //       return <Tag label={"Incompleto"} color="error" icon={<SentimentDissatisfiedOutlinedIcon />} >
  //               Incompleto
  //             </Tag>
  //       // return  <Stack direction="row" spacing={1}>
  //       //             <Chip icon={<SentimentSatisfiedOutlinedIcon />} label={"Incompleto"} color="error"/>
  //       //         </Stack>
  //   }else if(status === "informed") {
  //     return <Tag label={"Pendente"} color="warning" icon={<SentimentDissatisfiedOutlinedIcon />} >
  //             Pendente
  //           </Tag>
  //     // return  <Stack  direction="row" spacing={1}>
  //     //           <Chip icon={<SentimentDissatisfiedOutlinedIcon />} label={"Pendente"} className="btn btn-outline-warning" color="warning"/>
  //     //       </Stack>
  //   }
  //   else {
  //     return <Tag label={"Incompleto"} color="blue" icon={<SentimentSatisfiedOutlinedIcon />} >
  //               Autorizado
  //             </Tag>
  //       // return  <Stack  direction="row" spacing={1}>
  //       //             <Chip icon={<SentimentDissatisfiedOutlinedIcon />} label={"Autorizado"} color="primary"/>
  //       //         </Stack>
  //   }
  // }
  function renderStatusColor(status) {
    const chipStyle = {
      minWidth: '100px',
      maxWidth: '150px',
    };

    const commonChip = (label, color) => (
      <Stack direction="row" spacing={1}>
        <Chip label={label} color={color} style={chipStyle} />
      </Stack>
    );

    switch (status) {
      case 'informed':
        return commonChip("Pendente", 'warning');
      case 'incomplete':
        return commonChip("Incompleto", 'error');
      default:
        return commonChip("Autorizado", 'primary');
    }
  }

  function deleteDriver(id){
    if (user.perfil === "Master") {

      var result = window.confirm("Deseja mesmo excluir esse Motorista ? ");
      if (result === true) {
          firebase.firestore()
          .collection('drivers_users')
          .doc(id)
          .delete()
          .then(() => {
            alert("Documento excluído com sucesso!");
            fetchData();
          })
      } else {
        return;
      }
    }
  }

  const getColumnSearchProps = (dataIndex) => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters, close }) => (
      <div
        style={{
          padding: 8,
        }}
        onKeyDown={(e) => e.stopPropagation()}
      >
        <Input
          ref={searchInput}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys[0]}
          onChange={(e) => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => handleSearch(selectedKeys, confirm, dataIndex)}
          style={{
            marginBottom: 8,
            display: 'block',
          }}
        />
        <Space>
          <Button
            type="primary"
            onClick={() => handleSearch(selectedKeys, confirm, dataIndex)}
            icon={<SearchOutlined />}
            size="small"
            style={{
              width: 90,
            }}
          >
            Search
          </Button>
          <Button
            onClick={() => clearFilters && handleReset(clearFilters)}
            size="small"
            style={{
              width: 90,
            }}
          >
            Reset
          </Button>
          <Button
            type="link"
            size="small"
            onClick={() => {
              confirm({
                closeDropdown: false,
              });
              setSearchText(selectedKeys[0]);
              setSearchedColumn(dataIndex);
            }}
          >
            Filter
          </Button>
          <Button
            type="link"
            size="small"
            onClick={() => {
              close();
            }}
          >
            close
          </Button>
        </Space>
      </div>
    ),
    
    filterIcon: (filtered) => (
      <SearchOutlined
        style={{
          color: filtered ? '#1677ff' : undefined,
        }}
      />
    ),

    onFilter: (value, record) =>
      record[dataIndex].toString().toLowerCase().includes(value.toLowerCase()),
    onFilterDropdownOpenChange: (visible) => {
      if (visible) {
        setTimeout(() => searchInput.current?.select(), 100);
      }
    },

    render: (text) =>
      searchedColumn === dataIndex ? (
        <Highlighter
          highlightStyle={{
            backgroundColor: '#ffc069',
            padding: 0,
          }}
          searchWords={[searchText]}
          autoEscape
          textToHighlight={text ? text.toString() : ''}
        />
      ) : (
        text
      ),
  });

  const columns = [
    {
      title: 'Nome',
      dataIndex: 'name',
      key: 'name',
      width: '30%',
      ...getColumnSearchProps('name'),
      sorter: (a, b) => a.name.localeCompare(b.name),
    },
    {
      title: 'CPF',
      dataIndex: 'cpf',
      key: 'cpf',
      width: '20%',
      ...getColumnSearchProps('cpf'),
      render: (text) => {
        return <InputMask mask="999.999.999-99" value={text} disabled style={{
          border: 'none',
          backgroundColor: 'transparent',
          width: 'auto',
          padding: '0 5px',
          fontSize: '14px',
          color: '#444',
        }}/>;
      },
    },
    {
      title: 'E-mail',
      dataIndex: 'email',
      key: 'email',
      ...getColumnSearchProps('email'),
    },
    {
      title: 'Status',
      dataIndex: 'statusDriver',
      key: 'statusDriver',
      render: (_, value) => (
        <span>
          {renderStatusColor(value.statusDriver)}
        </span>
      ),
    },
    {
      title: 'Ações',
      width: '10%',
      // dataIndex: 'data',
      key: 'action',
          render: (_, record) => (
              <Space size="middle">
                <Link to={'/driverList/' + record.id}>
                      <EditOutlinedIcon />
                  </Link>
                {
                  <Link to={'#'}>
                    <DeleteOutlinedIcon onClick={(e) => deleteDriver(record.id)} color='error'/>
                  </Link>
                }
              </Space>
          ),
    },
  ];
  return <Table columns={columns} dataSource={datas} />;

};
export default DataDriverTable;