import React, { useRef, useState, useEffect } from 'react';
import { SearchOutlined } from '@ant-design/icons';
import Highlighter from 'react-highlight-words';
import { Button, Input, Space, Table, Tooltip } from 'antd';
import Typography from '@mui/material/Typography';
import { Avatar, Card, Divider, List, Modal } from '@mui/material';
import { Link, useNavigate } from "react-router-dom";
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';
import DeleteOutlinedIcon from '@mui/icons-material/DeleteOutlined';
import firebase from '../../config/firebase';
import { useSelector } from 'react-redux';
import Stack from '@mui/material/Stack';
import { Chip, Badge, Box, CardActionArea, CardContent, ListItem, ListItemAvatar, ListItemText } from '@mui/material';
import freightService from '../../service/freight.service';
import EditNotificationsOutlinedIcon from '@mui/icons-material/EditNotificationsOutlined';
import { format } from 'date-fns';
import { ContentCopy } from '@mui/icons-material';
require('firebase/auth');

const DriverBadge = ({ recordId }) => {
  const [driversInFila, setDriversInFila] = useState([]);

  useEffect(() => {
    const fetchDrivers = async () => {
      const db = firebase.firestore();
      const listDriverInFila = [];
      const result = await db.collection('freight').doc(recordId).collection('queue').get();
      result.docs.forEach(doc => {
        listDriverInFila.push({ id: doc.id, ...doc.data() });
      });
      setDriversInFila(listDriverInFila);
    };

    fetchDrivers();
  }, [recordId]);

  return (
    <Link to={'#' + recordId}>
      {driversInFila.length > 0 ? (
        <Badge badgeContent={driversInFila.length} color="success">
          <EditNotificationsOutlinedIcon color='primary' />
        </Badge>
      ) : (
        <EditNotificationsOutlinedIcon color='primary' />
      )}
    </Link>
  );
};

const DataFreteTable = ({ data }) => {
  const [searchText, setSearchText] = useState('');
  const [searchedColumn, setSearchedColumn] = useState('');
  const [openModal, setOpenModal] = useState(false);
  const [driversInFila, setDriversInFila] = useState([]);
  const [datas, setData] = useState([]);

  const searchInput = useRef(null);

  const user = useSelector(state => state.user);

  let navigate = useNavigate();

  const getDriversQueue = (id) => {
    const db = firebase.firestore();
    const listDriverInFila = [];
    db.collection('freight').doc(id).collection('queue')
      .get().then(async (result) => {
        result.docs.forEach(doc => {
          listDriverInFila.push({
            id: doc.id,
            ...doc.data()
          });
        });
        setDriversInFila(listDriverInFila);
        handleOpen();
      }).catch(error => {
        console.log(error)
      });
  };

  const fetchData = async () => {
    // const documents = data
    const snapshot = await firebase.firestore().collection('freight').get();
    const documents = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    // documents.sort((a, b) => {
    //   return b.firstDelivery.dateColeta - a.firstDelivery.dateColeta || b.firstDelivery.dateColeta - a.firstDelivery.dateColeta;
    // });
    setData(documents);
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleOpen = () => {
    setOpenModal(true);
  };

  const handleClose = () => {
    setOpenModal(false);
  };

  const handleSearch = (selectedKeys, confirm, dataIndex) => {
    confirm();
    setSearchText(selectedKeys[0]);
    setSearchedColumn(dataIndex);
  };

  const handleReset = (clearFilters) => {
    clearFilters();
    setSearchText('');
  };

  const deleteEmb = (id) => {
    if (user.perfil === "Master") {
      var result = window.confirm("Deseja mesmo excluir ? ");
      if (result === true) {
        // freightService.deleteFreight(id)
        //   .then(() => {
        //     alert("Frete excluído com sucesso!");
        //     fetchData(); // Executa fetchData após a exclusão ser bem-sucedida
        //   })
        // .catch(error => {
        //   console.error("Erro ao deletar o frete: ", error);
        // });
        firebase.firestore()
        .collection('freight')
        .doc(id)
        .delete()
        .then(() => {
          alert("Frete excluído com sucesso!");
          fetchData();
        })
      } else {
        return;
      }
    } else {
      alert("Você não tem privilégio suficiente para excluir um Cliente, contate algum usuário master.");
    }
  };

  const style = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: 400,
  };

  function renderStatusColor(status) {
    const chipStyle = {
      minWidth: '100px',
      maxWidth: '150px',
    };

    const commonChip = (label, color) => (
      <Stack direction="row" spacing={1}>
        <Chip label={label} color={color} style={chipStyle} />
      </Stack>
    );

    switch (status) {
      case 'Contratado':
        return commonChip(status, 'primary');
      case 'Pendente de contratação':
      case 'Em Analise de perfil':
        return commonChip(status, 'warning');
      case 'Em Analise do motorista':
      case 'Em transito':
        return commonChip(status, 'success');
      case 'Entregue':
        return commonChip(status, 'primary');
      case 'Finalizado':
        return commonChip(status, 'error');
      default:
        return commonChip(status, 'warning');
    }
  }

  const getColumnSearchProps = (dataIndex) => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters, close }) => (
      <div
        style={{
          padding: 8,
        }}
        onKeyDown={(e) => e.stopPropagation()}
      >
        <Input
          ref={searchInput}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys[0]}
          onChange={(e) => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => handleSearch(selectedKeys, confirm, dataIndex)}
          style={{
            marginBottom: 8,
            display: 'block',
          }}
        />
        <Space>
          <Button
            type="primary"
            onClick={() => handleSearch(selectedKeys, confirm, dataIndex)}
            icon={<SearchOutlined />}
            size="small"
            style={{
              width: 90,
            }}
          >
            Search
          </Button>
          <Button
            onClick={() => clearFilters && handleReset(clearFilters)}
            size="small"
            style={{
              width: 90,
            }}
          >
            Reset
          </Button>
          <Button
            type="link"
            size="small"
            onClick={() => {
              confirm({
                closeDropdown: false,
              });
              setSearchText(selectedKeys[0]);
              setSearchedColumn(dataIndex);
            }}
          >
            Filter
          </Button>
          <Button
            type="link"
            size="small"
            onClick={() => {
              close();
            }}
          >
            close
          </Button>
        </Space>
      </div>
    ),
    filterIcon: (filtered) => (
      <SearchOutlined
        style={{
          color: filtered ? '#1677ff' : undefined,
        }}
      />
    ),
    onFilter: (value, record) => {
      const dataIndexArray = Array.isArray(dataIndex) ? dataIndex : [dataIndex];
      let recordValue = record;
      for (const index of dataIndexArray) {
        recordValue = recordValue[index];
      }
      if (typeof value === 'string') {
        return recordValue?.toString().toLowerCase().includes(value.toLowerCase());
      } else {
        return recordValue === value;
      }
    },
    onFilterDropdownOpenChange: (visible) => {
      if (visible) {
        setTimeout(() => searchInput.current?.select(), 100);
      }
    },
    render: (text) =>
      searchedColumn === dataIndex ? (
        <Highlighter
          highlightStyle={{
            backgroundColor: '#ffc069',
            padding: 0,
          }}
          searchWords={[searchText]}
          autoEscape
          textToHighlight={text ? text.toString() : ''}
        />
      ) : (
        text
      ),
  });

  const columns = [
    {
      title: 'Data Coleta',
      dataIndex: ['firstDelivery', 'dateColeta'],
      key: 'firstDelivery',
      align: 'center',
      width: '20%',
      render: (dataColeta) => (
        dataColeta && dataColeta !== "" && dataColeta != null ?
          `${format(new Date(dataColeta), 'dd/MM/yyyy')}`
          : ""
      ),
    },
    {
      title: 'Nome Pagador',
      dataIndex: ['clientPayment', 'name'],
      key: 'name',
      align: 'center',
      width: '27%',
      ...getColumnSearchProps(['clientPayment', 'name']),
    },
    {
      title: 'Origem',
      dataIndex: ['firstDelivery', 'city'],
      key: 'firstDelivery',
      align: 'center',
      width: '22%',
      ...getColumnSearchProps(['firstDelivery', 'city']),
    },
    {
      title: 'Destino',
      dataIndex: ['lastDelivery', 'city'],
      key: 'lastDelivery',
      align: 'center',
      width: '22%',
      ...getColumnSearchProps(['lastDelivery', 'city']),
    },
    {
      title: 'Valor do Frete',
      dataIndex: ['freight', 'valueFreightage'],
      key: 'freight',
      align: 'center',
      width: '22%',
      ...getColumnSearchProps(['freight', 'valueFreightage']),
      render: (valueFreightage) => (
        `${(valueFreightage || 0).toLocaleString('pt-br', { style: 'currency', currency: 'BRL' })}`
      ),
    },
    {
      title: 'Pagando ao Motorista',
      dataIndex: 'driver',
      key: 'driver',
      align: 'center',
      width: '30%',
      render: (driver) => (
        `${(driver.valueInitial || 0).toLocaleString('pt-br', { style: 'currency', currency: 'BRL' })}`
      ),
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      align: 'center',
      ...getColumnSearchProps(['status', 'describe']),
      render: (status) => {
        const describeText = status.describe === 'Pendente de contratação' ? 'P.Contratação' : status.describe;
        return (
          <Tooltip title={status.describe}>
            <div>
              {renderStatusColor(describeText)}
            </div>
          </Tooltip>
        );
      },
    },
    {
      title: 'Editar',
      width: '10%',
      align: 'center',
      key: 'action',
      render: (_, record) => (
        <Space size="middle">
          <Link to={'#' + record.id} onClick={() => getDriversQueue(record.id)}>
            <DriverBadge recordId={record.id} />
          </Link>
          <Link to={'/freight/' + record.id}>
            <EditOutlinedIcon />
          </Link>
          <Link to={`/freight/${record.id}?copy=true`}>
            <ContentCopy />
          </Link>
          <Link to={'#'}>
            <DeleteOutlinedIcon onClick={() => deleteEmb(record.id)} color='error' />
          </Link>
        </Space>
      ),
    },
  ];

  return (
    <>
      <Modal
        open={openModal}
        onClose={handleClose}
        aria-labelledby="parent-modal-title"
        aria-describedby="parent-modal-description"
      >
        <Box sx={{ ...style, width: 600 }}>
          <Card sx={{ maxWidth: 600 }}>
            <CardActionArea>
              <CardContent>
                <Typography gutterBottom variant="h5" component="div">
                  Motoristas na fila
                </Typography>
                {
                  driversInFila.length < 1 ?
                    <Typography gutterBottom color={"error"} component="div">
                      Não há motorista em espera para esse frete no momento
                    </Typography>
                    :
                    driversInFila.map(item => (
                      <div className='row' key={item.id}>
                        <List sx={{ width: '100%', maxWidth: 800, bgcolor: 'background.paper' }}>
                          <ListItem alignItems="flex-start">
                            <ListItemAvatar>
                              <Avatar alt={item.driver_name} />
                            </ListItemAvatar>
                            <ListItemText
                              primary={item.driver_name}
                              secondary={
                                <React.Fragment>
                                  <Typography
                                    sx={{ display: 'inline' }}
                                    component="span"
                                    variant="body2"
                                    color="text.primary"
                                  >
                                    Na fila de espera desde: {format(new Date(item.registrationInLineTime.seconds * 1000), 'dd/MM/yyyy HH:mm:ss')}
                                  </Typography>
                                </React.Fragment>
                              }
                            />
                            <ListItemText>
                              <Link to={'/driverList/' + item.driver_user}>
                                <EditOutlinedIcon />
                              </Link>
                            </ListItemText>
                          </ListItem>
                          <Divider variant="inset" component="li" />
                        </List>
                      </div>
                    ))
                }
              </CardContent>
            </CardActionArea>
          </Card>
        </Box>
      </Modal>

      <Table columns={columns} dataSource={datas} rowKey="id" />
    </>
  );
};

export default DataFreteTable;