
import React from 'react';
import Zoom from 'react-medium-image-zoom'
import 'react-medium-image-zoom/dist/styles.css'

function ImageZoom({title, source, height, width}){
    return(
        <>
            <Zoom>
                <img
                    alt={title}
                    src={source && source}
                    width={height}
                    height={width}
                />
             </Zoom>
        </>
    );
}

export default ImageZoom;