import React, { useEffect, useState } from "react";
import "./style.css";
import { useSelector } from "react-redux";
import { Navigate, useParams } from "react-router-dom";
import PersistentDrawerLeft from "../../components/navMenu/NavMenu";
import MapComponent from "../../components/MAPA-COMP/mapa-comp";
import firebase from '../../config/firebase';
import MapRoteComponent from "../../components/MAPA-COMP/mapa-roteirizada";

require("firebase/auth");

export default function ViewerFreights() {

  const db = firebase.firestore();

  const { id, idDriver } = useParams();

  const [freightList, setFreightList] = useState([]);
  const [freight, setFreight] = useState([]);
  const [stoppingList, setStoppingList] = useState([]);
  const [points, setPoints] = useState([]);
  const [freightData, setFreightData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  const fetchFreightData = async () => {
      
      try {
          const freightDocRef = db.collection("freight").doc(id); 
          const freightDoc = await freightDocRef.get();

          if (!freightDoc.exists) {
              throw new Error("Document not found");
          }

          const freightData = {
              id: freightDoc.id,
              ...freightDoc.data()
          };

          const subcollectionSnapshot = await freightDocRef.collection("stopping_points").get(); 


          const subcollectionData = subcollectionSnapshot.docs.map(subDoc => ({
              id: subDoc.id,
              ...subDoc.data()
          }));

          setFreightData({
              ...freightData,
              subcollectionData
          });

          var pontos = [];

          subcollectionData.map((item) => {

              pontos.push({
                  coords: [item.latitude, item.longitude],
                  popupText: '<strong>' + item.name + '</strong><br/>' + item.logradouro + ', ' + item.number + ', ' + item.city + ' - ' + item.uf + ',  ' + item.cep
              });
              
          });
          
          console.log(freightData)
          setPoints(pontos);
          
      } catch (err) {
          setError(err);
          console.log(err)
      } finally {
          setLoading(false);
      }
  };

  useEffect(()=> {
      
      fetchFreightData();

  }, []);
  return (
    <>
      {useSelector((state) => state.usuarioLogado) > 0 ? (
        <PersistentDrawerLeft
          divOpen={
            <div className="freight-content-details">
           
                  <div className="container">

                      {points.length > 0 ? (
                          <MapComponent points={points} idFreight={id}/> 
                          // <MapRoteComponent />
                      ) : (
                          <p>Loading...</p>
                      )}

                  </div>

            </div>
          }
        />
      ) : (
        <Navigate to="/login" />
      )}
    </>

  );
  
}
