    function validInput(){

        if(!cnpjPayingCustomer){
            showMessage("O campo CNPJ da cessão Cliente Pagador precisa ser preenchido");
            document.getElementById("cnpjPayingCustomer").focus() 
            return;
        }
        if(!payingCustomer){
            showMessage("O campo Cliente da cessão Cliente Pagador precisa ser preenchido");
            document.getElementById("payingCustomer").focus()
            return;
        }
        if(!valueDriverInitial){
            showMessage("O campo Pagamento De: e descarga da cessão Motorista precisa ser preenchido");
            document.getElementById("valueDriverInitial").focus() 
            return;
        }
        if(!valueDriverFinal){
            showMessage("O campo Pagamento Até: e descarga da cessão Motorista precisa ser preenchido");
            document.getElementById("valueDriverFinal").focus() 
            return;
        }
        if(!occupation){
            showMessage("O campo Ocupação da cessão Veículo precisa ser preenchido");
            document.getElementById("occupation").focus() 
            return;
        }
        if(!freeOfCharge){
            showMessage("O campo Livre de Carga e descarga da cessão Veículo precisa ser preenchido");
            document.getElementById("freeOfCharge").focus() 
            return;
        }
        if(!product){
            showMessage("O campo Produto e descarga da cessão Frete precisa ser preenchido");
            document.getElementById("product").focus() 
            return;
        }
        if(!seller){
            showMessage("O campo Vendedor e descarga da cessão Frete precisa ser preenchido");
            document.getElementById("seller").focus() 
            return;
        }
        if(!valueNF){
            showMessage("O campo Valor NF e descarga da cessão Frete precisa ser preenchido");
            document.getElementById("valueNF").focus() 
            return;
        }
        if(!weightCargo){
            showMessage("O campo Peso da Carga (Kg) e descarga da cessão Frete precisa ser preenchido");
            document.getElementById("weightCargo").focus() 
            return;
        }
        if(!valueFreightage){
            showMessage("O campo Valor do Frete e descarga da cessão Frete precisa ser preenchido");
            document.getElementById("valueFreightage").focus()
            return;
        }
    }

